def create_default_section_pages(apps, schema_editor):
    SectionPage = apps.get_model('blog', 'SectionPage')
    SectionPageTag = apps.get_model('blog', 'SectionPageTag')
    SectionPageFilter = apps.get_model('blog', 'SectionPageFilter')
    Category = apps.get_model('blog', 'Category')

    for section, data in SECTION_PAGES.items():
        page, _ = SectionPage.objects.get_or_create(section=section)
        for field in [
            'title', 'eyebrow', 'description', 'manifesto', 'index_label',
            'stat_one_value', 'stat_one_label', 'stat_two_value', 'stat_two_label',
            'empty_text', 'filter_aria_label', 'extra',
        ]:
            setattr(page, field, data[field])
        page.save()

        for index, tag in enumerate(data['tags'], start=1):
            SectionPageTag.objects.update_or_create(
                section_page=page,
                name=tag,
                defaults={'sort_order': index * 10, 'is_visible': True},
            )

        filters = list(data['filters'])
        if section in {'editing', 'games'}:
            filters.extend(
                (category.name, category.slug)
                for category in Category.objects.filter(section=section).order_by('name')
            )

        for index, (name, slug) in enumerate(filters, start=1):
            SectionPageFilter.objects.update_or_create(
                section_page=page,
                name=name,
                defaults={'slug': slug, 'sort_order': index * 10, 'is_visible': True},
            )


def delete_default_section_pages(apps, schema_editor):
    SectionPage = apps.get_model('blog', 'SectionPage')
    SectionPage.objects.filter(section__in=SECTION_PAGES.keys()).delete()


